const isClearDevCandidateCurrentRound = `-- name: IsClearDevCandidateCurrentRound :one
SELECT CAST(
    COALESCE((
        SELECT MAX(candidate_event.sequence)
        FROM cleardev_project_events AS candidate_event
        WHERE candidate_event.subject_type IN ('CANDIDATE_COMMIT')
          AND candidate_event.subject_id = ?1
          AND candidate_event.action = 'REGISTER_CANDIDATE'
          AND candidate_event.outcome = 'ACCEPTED'
    ), 0) > COALESCE((
        SELECT MAX(restart_event.sequence)
        FROM cleardev_project_events AS restart_event
        WHERE restart_event.subject_type IN ('WORK_ITEM', 'DEVELOPMENT_TASK')
          AND restart_event.subject_id = ?2
          AND restart_event.action IN ('RESTART_WORK_ITEM', 'RESTART_DEVELOPMENT_TASK')
          AND restart_event.outcome = 'ACCEPTED'
    ), 0)
AS INTEGER)
`

type IsClearDevCandidateCurrentRoundParams struct {
	CandidateID       string
	DevelopmentTaskID string
}

func (q *Queries) IsClearDevCandidateCurrentRound(ctx context.Context, arg IsClearDevCandidateCurrentRoundParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, isClearDevCandidateCurrentRound, arg.CandidateID, arg.DevelopmentTaskID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

